import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

/**
 * Load the native FSEvents binding. Throws a descriptive error on
 * non-macOS platforms or when the optional dependency failed to install.
 */
export function loadFsevents() {
  if (process.platform !== 'darwin') {
    throw new Error(`FSEvents is only available on macOS (current platform: ${process.platform})`);
  }
  try {
    return require('fsevents');
  } catch (err) {
    throw new Error(`Failed to load the native fsevents module: ${err.message}`);
  }
}

/**
 * Watch a directory tree for filesystem changes via FSEvents.
 *
 * @param {string} path - Directory to watch (recursively).
 * @param {(event: object) => void} onEvent - Called with fsevents' decoded info:
 *   { path, event, type, changes: { inode, finder, access, xattrs }, flags, id }
 * @returns {() => Promise<void>} Stops the watcher.
 */
export function watch(path, onEvent) {
  const fsevents = loadFsevents();
  return fsevents.watch(path, (changedPath, flags, id) => {
    const info = fsevents.getInfo(changedPath, flags);
    onEvent({ ...info, id });
  });
}
EOF
cat > bin/mac-fswatch.js <<'EOF'
#!/usr/bin/env node
import { resolve } from 'node:path';
import { watch } from '../src/index.js';

const target = resolve(process.argv[2] ?? '.');

let stop;
try {
  stop = watch(target, (e) => {
    console.log(JSON.stringify({ event: e.event, type: e.type, path: e.path, flags: e.flags, id: String(e.id) }));
  });
} catch (err) {
  console.error(`mac-fswatch: ${err.message}`);
  process.exit(1);
}

console.error(`Watching ${target} (Ctrl+C to stop)`);

process.on('SIGINT', async () => {
  await stop();
  process.exit(0);
});
EOF
chmod +x bin/mac-fswatch.js
cat > test/index.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { watch, loadFsevents } from '../src/index.js';

const isMac = process.platform === 'darwin';

test('loadFsevents rejects non-macOS platforms', { skip: isMac }, () => {
  assert.throws(loadFsevents, /only available on macOS/);
});

test('watch reports a created file', { skip: !isMac, timeout: 10_000 }, async () => {
  const dir = await mkdtemp(join(tmpdir(), 'mac-fswatch-'));
  const file = join(dir, 'hello.txt');
  let stop;
  try {
    const seen = new Promise((res) => {
      stop = watch(dir, (e) => {
        if (e.path.endsWith('hello.txt') && e.event === 'created') res(e);
      });
    });
    await new Promise((r) => setTimeout(r, 200)); // let the FSEvents stream start
    await writeFile(file, 'hi');
    const event = await seen;
    assert.equal(event.type, 'file');
  } finally {
    await stop?.();
    await rm(dir, { recursive: true, force: true });
  }
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
.DS_Store
transcript.jsonl
EOF
cat > README.md <<'EOF'
# mac-fswatch

A macOS file-watching tool built directly on Apple's FSEvents API via the
native [`fsevents`](https://github.com/fsevents/fsevents) binding.

## Requirements

- macOS
- Node.js >= 18

`fsevents` is an optional, darwin-only dependency, so `npm install` won't fail
on other platforms — but the watcher only runs on macOS.

## Usage

```sh
npm install
npx mac-fswatch [dir]     # prints one JSON line per change
```

```js
import { watch } from 'mac-fswatch';

const stop = watch('/some/dir', (e) => {
  // e.event: created | modified | deleted | moved | root-changed | cloned | unknown
  // e.type:  file | directory | symlink
  console.log(e.event, e.type, e.path);
});

await stop();
```

## Tests

```sh
npm test
```
EOF
npm install 2>&1 | tail -5; npm test 2>&1 | tail -12

